def start(self):
        """Start the consumer.  This starts a listen loop on a zmq.PULL socket,
        calling ``self.handle`` on each incoming request and pushing the response
        on a zmq.PUSH socket back to the producer."""
        self.socket = self.context.socket(zmq.PULL)
        self.socket.bind(self.endpoint)
        self.push_socket = self.context.socket(zmq.PUSH)
        self.push_socket.connect(self.push_endpoint)
        self.logger.info("Starting consumer on %s", self.endpoint)
        self.logger.info("Connecting to producer on %s", self.push_endpoint)
        while True:
            try:
                self.handle(self.socket.recv_json())
            except zmq.ZMQError as e:
                if e.errno == zmq.ETERM:
                    break
                else:
                    raise

